package com.hireflow.api.interview; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/interviews") public class InterviewController {private final InterviewRepository r; public InterviewController(InterviewRepository x){r=x;} @GetMapping public List<Interview> mine(@RequestHeader("X-User-Email")String e){return r.findByCandidateEmailOrderByScheduledAtDesc(e);} @PostMapping public Interview schedule(@RequestHeader("X-User-Email")String e,@RequestBody Map<String,String>b){Interview i=new Interview();i.setCandidateEmail(e);i.setApplicationId(Long.valueOf(b.get("applicationId")));i.setScheduledAt(LocalDateTime.parse(b.get("scheduledAt")));i.setType(b.getOrDefault("type","Technical"));i.setMeetingLink(b.getOrDefault("meetingLink",""));return r.save(i);}}